-- Base64Content stores only the raw base64 payload, without the "data:image/...;base64," prefix.
-- This seed upserts the professional Dana Gharaibeh SVG logo.

DECLARE @AssetKey NVARCHAR(120) = N'logo';
DECLARE @FileName NVARCHAR(255) = N'logo-dana-gharaibeh.svg';
DECLARE @MimeType NVARCHAR(120) = N'image/svg+xml';
DECLARE @Base64Content NVARCHAR(MAX) = N'';

IF EXISTS (SELECT 1 FROM dbo.Assets WHERE AssetKey = @AssetKey)
BEGIN
    UPDATE dbo.Assets
    SET FileName = @FileName,
        MimeType = @MimeType,
        Base64Content = @Base64Content,
        AltEn = N'Dana Gharaibeh logo',
        AltAr = N'شعار دانا غرايبة',
        IsActive = 1
    WHERE AssetKey = @AssetKey;
END
ELSE
BEGIN
    INSERT INTO dbo.Assets (AssetKey, FileName, MimeType, Base64Content, AltEn, AltAr, IsActive)
    VALUES (@AssetKey, @FileName, @MimeType, @Base64Content, N'Dana Gharaibeh logo', N'شعار دانا غرايبة', 1);
END

